{
  "$schema": "https://wpl.dev/schemas/wpl/v1.schema.json",
  "version": "1.6.0",
  "plan": {
    "id": "post-mi-12wk-general-fitness",
    "name": "12-Week Post-MI General Fitness Programme",
    "description": "A 12-week moderate-intensity general fitness programme for a 58-year-old male, six months post-myocardial infarction, cleared by cardiac rehab. All sessions are capped at <115 bpm (70% age-predicted HRmax). No Valsalva, no maximal lifts. Progressive overload is gradual and conservative.",
    "type": "hybrid",
    "visibility": "template",
    "metadata": {
      "created_at": "2025-01-01T00:00:00Z",
      "updated_at": "2025-01-01T00:00:00Z",
      "created_by": "fitness-ai",
      "tags": ["cardiac-rehab", "post-mi", "moderate-intensity", "general-fitness", "older-adult"],
      "difficulty": "beginner",
      "language": "en",
      "estimated_duration_days": 84
    },
    "goals": [
      {
        "id": "goal-cardiovascular",
        "type": "primary",
        "category": "cardiovascular_health",
        "name": "Improve cardiovascular endurance safely",
        "description": "Build aerobic base while keeping HR below 115 bpm at all times.",
        "target": {
          "metric": "resting_hr_bpm",
          "target_value": 65,
          "unit": "bpm",
          "measurement_type": "absolute"
        },
        "milestones": [
          { "id": "ms-cardio-1", "name": "Complete 20 min continuous cardio at <115 bpm", "reward_points": 50 },
          { "id": "ms-cardio-2", "name": "Complete 30 min continuous cardio at <115 bpm", "reward_points": 100 }
        ]
      },
      {
        "id": "goal-strength",
        "type": "secondary",
        "category": "muscular_strength",
        "name": "Build functional strength",
        "description": "Develop whole-body muscular strength using moderate loads, controlled breathing, and no Valsalva.",
        "target": {
          "metric": "session_rpe_avg",
          "target_value": 5,
          "unit": "rpe",
          "measurement_type": "absolute"
        },
        "milestones": [
          { "id": "ms-strength-1", "name": "Complete 3 full strength sessions in a week", "reward_points": 50 },
          { "id": "ms-strength-2", "name": "Maintain RPE 4-5 across all 12 weeks", "reward_points": 100 }
        ]
      },
      {
        "id": "goal-mobility",
        "type": "secondary",
        "category": "flexibility_mobility",
        "name": "Maintain and improve joint mobility",
        "description": "Daily mobility and stretching to support recovery and reduce injury risk.",
        "target": {
          "metric": "sit_and_reach_cm",
          "target_value": 30,
          "unit": "cm",
          "measurement_type": "absolute"
        },
        "milestones": [
          { "id": "ms-mobility-1", "name": "Complete mobility work 3x per week for 4 weeks", "reward_points": 40 }
        ]
      }
    ],
    "requirements": {
      "min_age": 50,
      "max_age": 70,
      "fitness_level": ["beginner", "deconditioned"],
      "equipment": [
        { "id": "eq-treadmill", "name": "Treadmill", "required": true, "alternatives": ["stationary_bike", "elliptical"] },
        { "id": "eq-dumbbells", "name": "Dumbbells", "required": true },
        { "id": "eq-cable-machine", "name": "Cable Machine", "required": true, "alternatives": ["resistance_bands"] },
        { "id": "eq-leg-press", "name": "Leg Press Machine", "required": false, "alternatives": ["goblet_squat"] },
        { "id": "eq-bench", "name": "Adjustable Bench", "required": true },
        { "id": "eq-foam-roller", "name": "Foam Roller", "required": true }
      ],
      "contraindications": [
        {
          "condition": "icd10:I21",
          "severity": "high",
          "action": "require_clearance",
          "affected_activities": []
        },
        {
          "condition": "acsm:cardiac_rehab_phase_2",
          "severity": "high",
          "action": "modify",
          "affected_activities": []
        },
        {
          "condition": "valsalva_manoeuvre",
          "severity": "high",
          "action": "exclude",
          "affected_activities": []
        },
        {
          "condition": "maximal_effort_lifts",
          "severity": "high",
          "action": "exclude",
          "affected_activities": []
        }
      ],
      "time_commitment": {
        "min_days_per_week": 3,
        "max_days_per_week": 4,
        "min_minutes_per_day": 40,
        "max_minutes_per_day": 60
      }
    },
    "personalization": {
      "inputs": [
        { "id": "input-resting-hr", "type": "number", "source": "wellness.hrv_rmssd_morning", "label": "Morning HRV (rMSSD)" },
        { "id": "input-sleep", "type": "number", "source": "wellness.sleep_hours_last_night", "label": "Sleep hours last night" },
        { "id": "input-rpe-yesterday", "type": "number", "source": "wellness.session_rpe_yesterday", "label": "Session RPE yesterday" }
      ],
      "rules": [
        {
          "id": "rule-reduce-intensity-poor-sleep",
          "condition": { "field": "wellness.sleep_hours_last_night", "op": "lt", "value": 6 },
          "actions": [{ "type": "modify_intensity", "scope": "day", "adjustment": "reduce_one_zone" }]
        },
        {
          "id": "rule-skip-if-high-rpe",
          "condition": { "field": "wellness.session_rpe_yesterday", "op": "gte", "value": 8 },
          "actions": [{ "type": "substitute_day_type", "scope": "day", "replacement": "active_recovery" }]
        }
      ]
    },
    "athlete_thresholds": {
      "hr_max_bpm": 162,
      "resting_hr_bpm": 70,
      "body_weight_kg": 85
    },
    "progress": {
      "checkpoints": [
        {
          "id": "cp-week4",
          "name": "4-Week Check-In",
          "at": { "value": 4, "unit": "weeks" },
          "measurements": [
            { "metric": "resting_hr_bpm" },
            { "metric": "body_weight_kg" },
            { "metric": "session_rpe_avg" },
            { "metric": "blood_pressure_systolic_mmhg" },
            { "metric": "blood_pressure_diastolic_mmhg" }
          ],
          "questions": [
            "Any chest pain, dizziness, or unusual shortness of breath during sessions?",
            "How is your energy level on rest days?",
            "Are you sleeping well?"
          ]
        },
        {
          "id": "cp-week8",
          "name": "8-Week Check-In",
          "at": { "value": 8, "unit": "weeks" },
          "measurements": [
            { "metric": "resting_hr_bpm" },
            { "metric": "body_weight_kg" },
            { "metric": "session_rpe_avg" },
            { "metric": "sit_and_reach_cm" },
            { "metric": "blood_pressure_systolic_mmhg" },
            { "metric": "blood_pressure_diastolic_mmhg" }
          ],
          "questions": [
            "Any cardiac symptoms since last check-in?",
            "Has your GP or cardiologist reviewed your progress?",
            "Rate your overall wellbeing 1-10."
          ]
        },
        {
          "id": "cp-week12",
          "name": "12-Week Final Assessment",
          "at": { "value": 12, "unit": "weeks" },
          "measurements": [
            { "metric": "resting_hr_bpm" },
            { "metric": "body_weight_kg" },
            { "metric": "body_fat_pct" },
            { "metric": "sit_and_reach_cm" },
            { "metric": "six_min_walk_m" },
            { "metric": "blood_pressure_systolic_mmhg" },
            { "metric": "blood_pressure_diastolic_mmhg" },
            { "metric": "session_rpe_avg" }
          ],
          "questions": [
            "How has your quality of life changed over 12 weeks?",
            "Are you ready to progress to a more advanced programme?",
            "Any ongoing symptoms to report to your cardiologist?"
          ]
        }
      ],
      "points_system": {
        "enabled": true,
        "rules": [
          { "action": "complete_training_day", "points": 20 },
          { "action": "complete_active_recovery_day", "points": 10 },
          { "action": "complete_checkpoint", "points": 50 },
          { "action": "seven_day_streak", "points": 75 }
        ]
      }
    },
    "notifications": [
      {
        "id": "notif-hr-warning",
        "enabled": true,
        "message": "Heart rate approaching limit. Reduce pace or load immediately and rest if needed.",
        "timing_reference": "hr_threshold_breach"
      },
      {
        "id": "notif-session-reminder",
        "enabled": true,
        "message": "Time for your session! Remember to bring your HR monitor and water.",
        "timing_offset": { "value": 30, "unit": "minutes" },
        "timing_reference": "session_start"
      },
      {
        "id": "notif-checkpoint",
        "enabled": true,
        "message": "Check-in week! Please complete your measurements before your next session.",
        "timing_reference": "checkpoint"
      }
    ],
    "phases": [
      {
        "id": "phase-1-foundation",
        "name": "Phase 1 — Foundation (Weeks 1–4)",
        "order": 1,
        "type": "base",
        "description": "Establish movement patterns, breathing technique (exhale on exertion — no Valsalva), and aerobic base. Very conservative loads. RPE 3–4. HR strictly <115 bpm.",
        "duration": { "value": 4, "unit": "weeks" },
        "weeks": [
          {
            "id": "p1-week1",
            "name": "Week 1",
            "order": 1,
            "days": [
              {
                "id": "p1w1-day1",
                "day_of_week": 1,
                "type": "training",
                "name": "Monday — Full Body Strength A",
                "estimated_duration_minutes": 50,
                "blocks": [
                  {
                    "id": "p1w1d1-warmup",
                    "type": "warmup",
                    "order": 1,
                    "structure": "circuit",
                    "activities": [
                      {
                        "id": "p1w1d1-wu-walk",
                        "type": "cardio",
                        "name": "Brisk Treadmill Walk",
                        "modality": "treadmill_walk",
                        "prescription": {
                          "type": "continuous",
                          "duration": { "value": 8, "unit": "minutes" },
                          "intensity": {
                            "type": "bpm",
                            "target": { "min_bpm": 90, "max_bpm": 105 }
                          }
                        }
                      },
                      {
                        "id": "p1w1d1-wu-arm-circles",
                        "type": "recovery",
                        "name": "Dynamic Warm-Up Mobility",
                        "category": "warmup_mobility",
                        "prescription": {
                          "duration": { "value": 4, "unit": "minutes" },
                          "exercises": [
                            { "id": "re-arm-circles", "type": "recovery_exercise", "name": "Arm Circles", "modality": "dynamic_stretch", "reps": 10, "sides": "both", "body_part": "front_delts" },
                            { "id": "re-leg-swings", "type": "recovery_exercise", "name": "Leg Swings", "modality": "dynamic_stretch", "reps": 10, "sides": "both", "body_part": "hip_flexors" },
                            { "id": "re-hip-circles", "type": "recovery_exercise", "name": "Hip Circles", "modality": "mobility_drill", "reps": 8, "sides": "both", "body_part": "glutes" }
                          ]
                        }
                      }
                    ]
                  },
                  {
                    "id": "p1w1d1-main",
                    "type": "main",
                    "order": 2,
                    "structure": "straight_sets",
                    "activities": [
                      {
                        "id": "p1w1d1-goblet-squat",
                        "type": "exercise",
                        "exercise_ref": "goblet_squat",
                        "name": "Goblet Squat",
                        "primary_muscles": ["quadriceps", "glutes"],
                        "secondary_muscles": ["hamstrings", "abs"],
                        "movement_pattern": "squat",
                        "target_rpe": 4,
                        "target_rir": 4,
                        "prescription": {
                          "type": "sets_reps",
                          "sets": 2,
                          "reps": { "min": 10, "max": 12 },
                          "rest": { "value": 90, "unit": "seconds" },
                          "tempo": { "eccentric": 3, "pause_bottom": 1, "concentric": 2, "pause_top": 0 },
                          "weight": { "type": "absolute", "value": 8, "unit": "kg" }
                        }
                      },
                      {
                        "id": "p1w1d1-db-row",
                        "type": "exercise",
                        "exercise_ref": "dumbbell_single_arm_row",
                        "name": "Dumbbell Single-Arm Row",
                        "primary_muscles": ["lats", "upper_back"],
                        "secondary_muscles": ["biceps", "rear_delts"],
                        "movement_pattern": "pull_horizontal",
                        "target_rpe": 4,
                        "target_rir": 4,
                        "prescription": {
                          "type": "sets_reps",
                          "sets": 2,
                          "reps": { "min": 10, "max": 12 },
                          "rest": { "value": 90, "unit": "seconds" },
                          "tempo": { "eccentric": 2, "pause_bottom": 1, "concentric": 2, "pause_top": 1 },
                          "weight": { "type": "absolute", "value": 8, "unit": "kg" }
                        }
                      },
                      {
                        "id": "p1w1d1-db-chest-press",
                        "type": "exercise",
                        "exercise_ref": "dumbbell_chest_press",
                        "name": "Dumbbell Chest Press (Flat Bench)",
                        "primary_muscles": ["chest"],
                        "secondary_muscles": ["front_delts", "triceps"],
                        "movement_pattern": "push_horizontal",
                        "target_rpe": 4,
                        "target_rir": 4,
                        "prescription": {
                          "type": "sets_reps",
                          "sets": 2,
                          "reps": { "min": 10, "max": 12 },
                          "rest": { "value": 90, "unit": "seconds" },
                          "tempo": { "eccentric": 3, "pause_bottom": 1, "concentric": 2, "pause_top": 0 },
                          "weight": { "type": "absolute", "value": 8, "unit": "kg" }
                        }
                      },
                      {
                        "id": "p1w1d1-cable-pulldown",
                        "type": "exercise",
                        "exercise_ref": "cable_lat_pulldown",
                        "name": "Cable Lat Pulldown (Light)",
                        "primary_muscles": ["lats"],
                        "secondary_muscles": ["biceps", "traps"],
                        "movement_pattern": "pull_vertical",
                        "target_rpe": 4,
                        "target_rir": 4,
                        "prescription": {
                          "type": "sets_reps",
                          "sets": 2,
                          "reps": { "min": 12, "max": 15 },
                          "rest": { "value": 90, "unit": "seconds" },
                          "tempo": { "eccentric": 2, "pause_bottom": 1, "concentric": 2, "pause_top": 0 },
                          "weight": { "type": "absolute", "value": 20, "unit": "kg" }
                        }
                      },
                      {
                        "id": "p1w1d1-db-shoulder-press",
                        "type": "exercise",
                        "exercise_ref": "dumbbell_shoulder_press",
                        "name": "Seated Dumbbell Shoulder Press",
                        "primary_muscles": ["side_delts", "front_delts"],
                        "secondary_muscles": ["triceps", "traps"],
                        "movement_pattern": "push_vertical",
                        "target_rpe": 4,
                        "target_rir": 4,
                        "prescription": {
                          "type": "sets_reps",
                          "sets": 2,
                          "reps": { "min": 10, "max": 12 },
                          "rest": { "value": 90, "unit": "seconds" },
                          "tempo": { "eccentric": 3, "pause_bottom": 0, "concentric": 2, "pause_top": 0 },
                          "weight": { "type": "absolute", "value": 6, "unit": "kg" }
                        }
                      },
                      {
                        "id": "p1w1d1-plank",
                        "type": "exercise",
                        "exercise_ref": "forearm_plank",
                        "name": "Forearm Plank (Breathe Continuously)",
                        "primary_muscles": ["abs"],
                        "secondary_muscles": ["spinal_erectors", "glutes"],
                        "movement_pattern": "anti_rotate",
                        "target_rpe": 3,
                        "prescription": {
                          "type": "time",
                          "sets": 2,
                          "duration": { "value": 20, "unit": "seconds" },
                          "rest": { "value": 60, "unit": "seconds" }
                        }
                      }
                    ]
                  },
                  {
                    "id": "p1w1d1-cooldown",
                    "type": "cooldown",
                    "order": 3,
                    "activities": [
                      {
                        "id": "p1w1d1-cd-walk",
                        "type": "cardio",
                        "name": "Easy Treadmill Walk Cool-Down",
                        "modality": "treadmill_walk",
                        "prescription": {
                          "type": "continuous",
                          "duration": { "value": 5, "unit": "minutes" },
                          "intensity": {
                            "type": "bpm",
                            "target": { "min_bpm": 70, "max_bpm": 95 }
                          }
                        }
                      },
                      {
                        "id": "p1w1d1-cd-stretch",
                        "type": "recovery",
                        "name": "Full-Body Static Stretch",
                        "category": "cooldown_stretch",
                        "prescription": {
                          "duration": { "value": 6, "unit": "minutes" },
                          "exercises": [
                            { "id": "re-quad-stretch", "type": "recovery_exercise", "name": "Standing Quad Stretch", "modality": "static_stretch", "hold_seconds": 30, "sides": "both", "body_part": "quadriceps", "intensity_rpe": 5 },
                            { "id": "re-chest-stretch", "type": "recovery_exercise", "name": "Doorway Chest Stretch", "modality": "static_stretch", "hold_seconds": 30, "sides": "both", "body_part": "chest", "intensity_rpe": 5 },
                            { "id": "re-hip-flexor-stretch", "type": "recovery_exercise", "name": "Kneeling Hip Flexor Stretch", "modality": "static_stretch", "hold_seconds": 30, "sides": "both", "body_part": "hip_flexors", "intensity_rpe": 5 }
                          ]
                        }
                      }
                    ]
                  }
                ]
              },
              {
                "id": "p1w1-day2",
                "day_of_week": 2,
                "type": "rest",
                "name": "Tuesday — Rest"
              },
              {
                "id": "p1w1-day3",
                "day_of_week": 3,
                "type": "training",
                "name": "Wednesday — Cardio & Core",
                "estimated_duration_minutes": 45,
                "blocks": [
                  {
                    "id": "p1w1d3-warmup",
                    "type": "warmup",
                    "order": 1,
                    "activities": [
                      {
                        "id": "p1w1d3-wu-walk",
                        "type": "cardio",
                        "name": "Easy Walk Warm-Up",
                        "modality": "treadmill_walk",
                        "prescription": {
                          "type": "continuous",
                          "duration": { "value": 5, "unit": "minutes" },
                          "intensity": {
                            "type": "bpm",
                            "target": { "min_bpm": 80, "max_bpm": 100 }
                          }
                        }
                      }
                    ]
                  },
                  {
                    "id": "p1w1d3-main-cardio",
                    "type": "main",
                    "order": 2,
                    "activities": [
                      {
                        "id": "p1w1d3-treadmill",
                        "type": "cardio",
                        "name": "Moderate Treadmill Walk/Jog",
                        "modality": "treadmill",
                        "prescription": {
                          "type": "continuous",
                          "duration": { "value": 20, "unit": "minutes" },
                          "intensity": {
                            "type": "bpm",
                            "target": { "min_bpm": 100, "max_bpm": 112 }
                          }
                        }
                      }
                    ]
                  },
                  {
                    "id": "p1w1d3-core",
                    "type": "main",
                    "order": 3,
                    "structure": "circuit",
                    "rounds": 2,
                    "rest_between_rounds": { "value": 90, "unit": "seconds" },
                    "activities": [
                      {
                        "id": "p1w1d3-dead-bug",
                        "type": "exercise",
                        "exercise_ref": "dead_bug",
                        "name": "Dead Bug (Exhale on Extension)",
                        "primary_muscles": ["abs"],
                        "secondary_muscles": ["hip_flexors", "spinal_erectors"],
                        "movement_pattern": "anti_rotate",
                        "target_rpe": 3,
                        "prescription": {
                          "type": "sets_reps",
                          "sets": 2,
                          "reps": { "target": 8 },
                          "rest": { "value": 60, "unit": "seconds" }
                        }
                      },
                      {
                        "id": "p1w1d3-bird-dog",
                        "type": "exercise",
                        "exercise_ref": "bird_dog",
                        "name": "Bird Dog",
                        "primary_muscles": ["spinal_erectors", "glutes"],
                        "secondary_muscles": ["abs"],
                        "movement_pattern": "anti_rotate",
                        "target_rpe": 3,
                        "prescription": {
                          "type": "sets_reps",
                          "sets": 2,
                          "reps": { "target": 8 },
                          "rest": { "value": 60, "unit": "seconds" }
                        }
                      },
                      {
                        "id": "p1w1d3-glute-bridge",
                        "type": "exercise",
                        "exercise_ref": "glute_bridge",
                        "name": "Glute Bridge",
                        "primary_muscles": ["glutes"],
                        "secondary_muscles": ["hamstrings", "abs"],
                        "movement_pattern": "hinge",
                        "target_rpe": 3,
                        "prescription": {
                          "type": "sets_reps",
                          "sets": 2,
                          "reps": { "min": 12, "max": 15 },
                          "rest": { "value": 60, "unit": "seconds" },
                          "tempo": { "eccentric": 2, "pause_bottom": 0, "concentric": 2, "pause_top": 2 }
                        }
                      }
                    ]
                  },
                  {
                    "id": "p1w1d3-cooldown",
                    "type": "cooldown",
                    "order": 4,
                    "activities": [
                      {
                        "id": "p1w1d3-cd-walk",
                        "type": "cardio",
                        "name": "Cool-Down Walk",
                        "modality": "treadmill_walk",
                        "prescription": {
                          "type": "continuous",
                          "duration": { "value": 5, "unit": "minutes" },
                          "intensity": {
                            "type": "bpm",
                            "target": { "min_bpm": 70, "max_bpm": 90 }
                          }
                        }
                      },
                      {
                        "id": "p1w1d3-cd-foam-roll",
                        "type": "recovery",
                        "name": "Foam Roll Lower Body",
                        "category": "cooldown_smr",
                        "prescription": {
                          "duration": { "value": 5, "unit": "minutes" },
                          "exercises": [
                            { "id": "re-fr-quads", "type": "recovery_exercise", "name": "Foam Roll Quads", "modality": "smr_foam_roll", "hold_seconds": 30, "sides": "both", "body_part": "quadriceps", "intensity_rpe": 5 },
                            { "id": "re-fr-calves", "type": "recovery_exercise", "name": "Foam Roll Calves", "modality": "smr_foam_roll", "hold_seconds": 30, "sides": "both", "body_part": "calves", "intensity_rpe": 5 }
                          ]
                        }
                      }
                    ]
                  }
                ]
              },
              {
                "id": "p1w1-day4",
                "day_of_week": 4,
                "type": "rest",
                "name": "Thursday — Rest"
              },
              {
                "id": "p1w1-day5",
                "day_of_week": 5,
                "type": "training",
                "name": "Friday — Full Body Strength B",
                "estimated_duration_minutes": 50,
                "blocks": [
                  {
                    "id": "p1w1d5-warmup",
                    "type": "warmup",
                    "order": 1,
                    "activities": [
                      {
                        "id": "p1w1d5-wu-bike",
                        "type": "cardio",
                        "name": "Stationary Bike Warm-Up",
                        "modality": "stationary_bike",
                        "prescription": {
                          "type": "continuous",
                          "duration": { "value": 8, "unit": "minutes" },
                          "intensity": {
                            "type": "bpm",
                            "target": { "min_bpm": 90, "max_bpm": 105 }
                          }
                        }
                      }
                    ]
                  },
                  {
                    "id": "p1w1d5-main",
                    "type": "main",
                    "order": 2,
                    "structure": "straight_sets",
                    "activities": [
                      {
                        "id": "p1w1d5-leg-press",
                        "type": "exercise",
